from tinydb import TinyDB
from tinydb.storages import MemoryStorage

db = TinyDB(storage=MemoryStorage)
db.insert_multiple([{'a':1},{'a':2},{'a':3}])

# Edge: whitespace string
try:
    print("update ' 1 ':", db.update({'a':10}, doc_ids=[' 1 ']))
except Exception as e:
    print("update ' 1 ' ->", type(e).__name__, e)

# Edge: float-like string
try:
    print("update '1.0':", db.update({'a':10}, doc_ids=['1.0']))
except Exception as e:
    print("update '1.0' ->", type(e).__name__, e)

# Edge: negative
try:
    print("update '-1':", db.update({'a':10}, doc_ids=['-1']))
except Exception as e:
    print("update '-1' ->", type(e).__name__, e)

# Edge: unicode digits
try:
    print("update '١' (arabic-indic 1):", db.update({'a':10}, doc_ids=['١']))
except Exception as e:
    print("update arabic ->", type(e).__name__, e)

# Edge: bool
try:
    print("update True:", db.update({'a':10}, doc_ids=[True]))
except Exception as e:
    print("update True ->", type(e).__name__, e)

# Edge: None
try:
    print("update None:", db.update({'a':10}, doc_ids=[None]))
except Exception as e:
    print("update None ->", type(e).__name__, e)

# Edge: float 1.0
try:
    print("update 1.0:", db.update({'a':10}, doc_ids=[1.0]))
except Exception as e:
    print("update 1.0 ->", type(e).__name__, e)
EOF
